import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "../reader-work/doc/B4/2/app/src/globe-tilt.ts";

function angleFromDown(cam: any) {
    const c = cam.center, p = cam.position;
    const d = { x: c.x - p.x, y: c.y - p.y, z: c.z - p.z };
    const dl = Math.hypot(d.x, d.y, d.z);
    const cl = Math.hypot(c.x, c.y, c.z);
    const dot = (d.x * c.x + d.y * c.y + d.z * c.z) / (dl * cl);
    return Math.acos(Math.max(-1, Math.min(1, -dot)));
}

describe("tiltGlobeCamera", () => {
    for (const pitch of [0.1, 0.6, 1.2]) {
        it(`holds pitch ${pitch} across zooms`, () => {
            const cam = createGeospatialCamera({ planetRadius: 100 });
            const c0 = { ...cam.center };
            const yaw0 = cam.yaw;
            expect(cam.radius).toBeCloseTo(400);
            tiltGlobeCamera(cam, pitch);
            expect(cam.pitch).toBeCloseTo(pitch, 9);
            expect(cam.radius).toBeCloseTo(400, 9);
            expect(cam.yaw).toBeCloseTo(yaw0, 9);
            expect(cam.center).toEqual(c0);
            expect(angleFromDown(cam)).toBeCloseTo(pitch, 5);
            for (const r of [300, 150, 50, 15, 250, 400]) {
                cam.radius = r;
                expect(cam.pitch).toBeCloseTo(pitch, 9);
                expect(angleFromDown(cam)).toBeCloseTo(pitch, 5);
            }
            setGeospatialOrientation(cam, { radius: 390 });
            expect(angleFromDown(cam)).toBeCloseTo(pitch, 5);
        });
    }
    it("without the fix the pitch would collapse at the resting zoom", () => {
        const cam = createGeospatialCamera({ planetRadius: 100 });
        setGeospatialOrientation(cam, { pitch: 0.6 });
        expect(cam.pitch).toBeLessThan(0.01);
    });
});
